  /** The help text of `config`, as `--help` shows it. */
  export function help(this: void, config: lib_args_Config): LuaMultiReturn<[string, undefined] | [undefined, lib_args_ArgsError]>
  export type ArgsError = lib_args_ArgsError
  export type Config = lib_args_Config
  export type Flag = lib_args_Flag
  export type FlagValue = lib_args_FlagValue
  export type Outcome = lib_args_Outcome
