// ===== lib:compress =====

/** The kinds of `lib_compress_DecodeError`. */
type lib_compress_DecodeErrorKind = "empty" | "max_size_zero" | "too_large" | "corrupt"

/** Why data was not decompressed. */
type lib_compress_DecodeError =
  /** There is no input: no format's stream is empty. */
  | { kind: "empty"; message: string; op: string }
  /** `max_size` is 0, which no output fits. */
  | { kind: "max_size_zero"; message: string; op: string }
  /** The output is more than `max_size` bytes. */
  | { kind: "too_large"; max_size: number; message: string; op: string }
  /** The input is not the format's, or is damaged. */
  | { kind: "corrupt"; format: lib_compress_Format; reason: string; message: string; op: string }

/** How `decode` decompresses. */
interface lib_compress_DecodeOptions {
  /** The most bytes it writes; more is an error. When not given: 256 MiB. */
  max_size?: number
}

/** The kinds of `lib_compress_EncodeError`. */
type lib_compress_EncodeErrorKind = "level_out_of_range" | "failed"

/** Why data was not compressed. */
type lib_compress_EncodeError =
  /** The format has no such level. */
  | { kind: "level_out_of_range"; format: lib_compress_Format; level: number; min: number; max: number; message: string; op: string }
  /** The encoder failed. */
  | { kind: "failed"; reason: string; message: string; op: string }

/** How `encode` compresses. */
interface lib_compress_EncodeOptions {
  /**
   * How hard to compress: higher is smaller and slower. Its range and the level used when not given are
   * the format's.
   */
  level?: number
}

/**
 * A compression format.
 * - `gzip`: gzip (RFC 1952): levels 0 to 9, 6 when not given.
 * - `zlib`: zlib (RFC 1950): levels 0 to 9, 6 when not given.
 * - `zstd`: Zstandard: levels 1 to 22, 3 when not given.
 * - `brotli`: Brotli: levels 0 to 11, 6 when not given.
 */
type lib_compress_Format = "gzip" | "zlib" | "zstd" | "brotli"

declare module "lib:compress" {
  /**
   * Compress `data`.
   *
   * ```luau
   * local packed = assert(compress.encode("gzip", string.rep("abc", 1000), { level = 9 }))
   * assert(#packed < 100)
   * assert(compress.decode("gzip", packed) == string.rep("abc", 1000))
   * ```
   */
  export function encode(this: void, format: lib_compress_Format, data: string, options?: lib_compress_EncodeOptions): LuaMultiReturn<[string, undefined] | [undefined, lib_compress_EncodeError]>
  /**
   * Decompress `data`, which was compressed as `format`.
   *
   * ```luau
   * local packed = assert(compress.encode("zstd", string.rep("a", 1000)))
   * local _, err = compress.decode("zstd", packed, { max_size = 10 })
   * assert(err ~= nil and err.kind == "too_large")
   * ```
   */
  export function decode(this: void, format: lib_compress_Format, data: string, options?: lib_compress_DecodeOptions): LuaMultiReturn<[string, undefined] | [undefined, lib_compress_DecodeError]>
  export type DecodeError = lib_compress_DecodeError
  export type DecodeOptions = lib_compress_DecodeOptions
  export type EncodeError = lib_compress_EncodeError
  export type EncodeOptions = lib_compress_EncodeOptions
  export type Format = lib_compress_Format
}

// ===== lib:crypto =====

/**
 * An AEAD cipher.
 * - `aes_128_gcm`: AES-128 in Galois/Counter Mode (16-byte key).
 * - `aes_256_gcm`: AES-256 in Galois/Counter Mode (32-byte key).
 * - `chacha20_poly1305`: ChaCha20-Poly1305, RFC 8439 (32-byte key).
 */
type lib_crypto_Algorithm = "aes_128_gcm" | "aes_256_gcm" | "chacha20_poly1305"

/** The kinds of `lib_crypto_CryptoError`. */
type lib_crypto_CryptoErrorKind = "invalid_key_length" | "invalid_nonce_length" | "ciphertext_too_short" | "decryption_failed" | "encryption_failed"

/** Why a message could not be encrypted or decrypted. */
type lib_crypto_CryptoError =
  /** The key is not the length the algorithm takes (`key_size`). */
  | { kind: "invalid_key_length"; expected: number; got: number; message: string; op: string }
  /** The nonce is not 12 bytes (`nonce_size`). */
  | { kind: "invalid_nonce_length"; expected: number; got: number; message: string; op: string }
  /** The ciphertext is shorter than the authentication tag, so it cannot be one. */
  | { kind: "ciphertext_too_short"; minimum: number; got: number; message: string; op: string }
  /**
   * The tag did not verify: the key, the nonce, the AAD or the ciphertext is not the one used to encrypt.
   * Which one is deliberately not said.
   */
  | { kind: "decryption_failed"; message: string; op: string }
  /** The backend refused to encrypt (in practice, a message too long for memory). */
  | { kind: "encryption_failed"; reason: string; message: string; op: string }

declare module "lib:crypto" {
  /**
   * Encrypt `plaintext` and authenticate it together with the optional `aad` (data that is sent in the clear and
   * must match at decrypt time). The result is the encrypted message followed by the 16-byte tag. Leaving `aad`
   * out is the same as an empty one.
   *
   * ```luau
   * local random = require("lib:random")
   * local key = assert(random.random_bytes(crypto.key_size("aes_256_gcm")))
   * local nonce = assert(random.random_bytes(crypto.nonce_size("aes_256_gcm")))
   * local sealed = assert(crypto.encrypt("aes_256_gcm", key, nonce, "attack at dawn", "header"))
   * assert(assert(crypto.decrypt("aes_256_gcm", key, nonce, sealed, "header")) == "attack at dawn")
   * local _, err = crypto.decrypt("aes_256_gcm", key, nonce, sealed, "other header")
   * assert(err ~= nil and err.kind == "decryption_failed")
   * ```
   */
  export function encrypt(this: void, algorithm: lib_crypto_Algorithm, key: string, nonce: string, plaintext: string, aad?: string): LuaMultiReturn<[string, undefined] | [undefined, lib_crypto_CryptoError]>
  /** Decrypt `ciphertext` (with its trailing tag), requiring `aad` to be the value bound when it was encrypted. */
  export function decrypt(this: void, algorithm: lib_crypto_Algorithm, key: string, nonce: string, ciphertext: string, aad?: string): LuaMultiReturn<[string, undefined] | [undefined, lib_crypto_CryptoError]>
  /** Every supported algorithm. */
  export function algorithms(this: void): lib_crypto_Algorithm[]
  /** The key length `algorithm` takes, in bytes. */
  export function key_size(this: void, algorithm: lib_crypto_Algorithm): number
  /** The nonce length `algorithm` takes, in bytes. */
  export function nonce_size(this: void, algorithm: lib_crypto_Algorithm): number
  /** The length of the authentication tag `encrypt` appends to the ciphertext, in bytes. */
  export function tag_size(this: void, algorithm: lib_crypto_Algorithm): number
  export type Algorithm = lib_crypto_Algorithm
  export type CryptoError = lib_crypto_CryptoError
}

