  /** What separates fields. @default "," */
  delimiter?: lib_csv_Symbol
  /** What quotes a field. @default "\"" */
  quote?: lib_csv_Symbol
  /** What escapes a quote inside a quoted field; the quote itself (doubled) when not given. */
