/**
 * A Unicode normalisation form.
 * - `nfc`: Canonical composition: combining sequences are composed (`e` + U+0301 becomes `é`).
 * - `nfd`: Canonical decomposition: composed characters are split into base and combining marks.
 * - `nfkc`: Compatibility composition: like `nfc`, and compatibility characters are folded too (`ﬁ` to `fi`).
 * - `nfkd`: Compatibility decomposition.
 */
type lib_unicode_Form = "nfc" | "nfd" | "nfkc" | "nfkd"

