  /**
   * Suspend every process of a running container.
   *
   * Yields the calling coroutine while it waits.
   */
  pause_container(name: vnd_bollard_ContainerName): LuaMultiReturn<[boolean, undefined] | [undefined, vnd_bollard_DockerError]>
  /**
   * Resume a paused container.
   *
   * Yields the calling coroutine while it waits.
   */
  unpause_container(name: vnd_bollard_ContainerName): LuaMultiReturn<[boolean, undefined] | [undefined, vnd_bollard_DockerError]>
  /**
   * Remove a container. A running one is `conflict` unless `force`, which kills it first.
   *
   * Yields the calling coroutine while it waits.
   */
  remove_container(name: vnd_bollard_ContainerName, opts?: vnd_bollard_RemoveContainer): LuaMultiReturn<[boolean, undefined] | [undefined, vnd_bollard_DockerError]>
  /**
   * A container's output, as a stream of pieces (a container with a TTY sends everything as `"console"`).
   * The stream ends after what there is, or with `follow` stays open for new output until the container
   * stops. A container that does not exist is the error of the first `next()`.
   *
   * ```luau
   * local docker = assert(bollard.connect())
   * local logs = docker:logs("web", { tail = 100 })
   * while true do
   *     local piece, err = logs:next()
   *     if piece == nil then
   *         assert(err == nil, tostring(err))
   *         break
   *     end
   *     print(piece.stream, piece.data)
   * end
   * ```
   */
  logs(name: vnd_bollard_ContainerName, opts?: vnd_bollard_Logs): mlua_Stream<vnd_bollard_LogPiece, vnd_bollard_DockerError>
  /**
   * One reading of a container's resource use: Docker's stats (`cpu_stats`, `memory_stats`, `networks`,
   * `blkio_stats`, ...).
   *
   * Yields the calling coroutine while it waits.
   */
  stats(name: vnd_bollard_ContainerName): LuaMultiReturn<[vnd_bollard_ContainerStatsResponse, undefined] | [undefined, vnd_bollard_DockerError]>
